\section{Introduction}

\subsection{Motivation}
Spectral graph theory for undirected graphs is mature: the eigenvalues of the
normalized Laplacian control connectivity, expansion, mixing and bipartiteness,
and Cheeger-type inequalities convert spectral quantities into combinatorial
ones with provable loss. For directed graphs the situation has long been less
satisfactory, since the natural adjacency operator is not self-adjoint and its
spectrum is complex.

One productive response is to study a \emph{family} of Hermitian operators
attached to a digraph rather than a single non-Hermitian one. Given nonnegative
arc weights $w_{uv}$ and $\omega \in \mathbb{C}$ with $|\omega| = 1$, the
\emph{rotated Laplacian} is $L_\omega = D - A_\omega$, where $A_\omega$ is the
weight matrix scaled by $\omega$; we take its quadratic form as the primary
object. The case $\omega = 1$ is the usual Laplacian and $\omega = -1$ the
signless Laplacian.

The combinatorial invariant at stake is the \emph{period} of a strongly
connected digraph: the greatest common divisor of the lengths of its closed
walks. Period $1$ means aperiodic; period $p > 1$ means the vertex set
partitions into $p$ classes cyclically permuted by every arc. Periodicity is a
fragile, all-or-nothing property of the exact arc set, so for applications one
wants a robust version: a real-valued score measuring how close a digraph is to
having period $p$, computable in polynomial time, and tied to a spectrum.

\subsection{The periodicity ratio}
Trevisan's bipartiteness ratio provides the template at $p = 2$: minimize
$\sum_{u,v} w_{uv}|x_u + x_v|^2$ over $x \in \{-1,0,1\}^V$, normalized by
volume. Replacing $\{-1,+1\}$, the square roots of unity, by the full group
$\mu_p$ of $p$-th roots of unity, and ``flip sign across an edge'' by ``rotate
by $\omega_p$ along an arc'', yields the periodicity ratio $\beta_p$ studied
here.

\subsection{Organization}
Section~\ref{sec:defs} fixes definitions. Section~\ref{sec:basic} records
nonnegativity, the arc-local characterization of zero energy, the bound
$\beta_p \le 2$, and reversal invariance. Section~\ref{sec:zeroset} contains
the main combinatorial characterization, the divisor-lattice structure, and an
explicit counterexample. Section~\ref{sec:markov} treats Markov chains.
Section~\ref{sec:quant} proves the quantization theorem, its rigidity
corollary, and sharpness. Sections~\ref{sec:algo}--\ref{sec:disc} discuss
algorithms, applications and open problems.

\section{Definitions}\label{sec:defs}

Throughout, $V$ is a finite nonempty vertex set and $w : V\times V \to
\mathbb{R}$ a weight function; unless stated otherwise $w_{uv} \ge 0$.

\begin{definition}[Rotated energy]
For $\omega \in \mathbb{C}$ and $x : V \to \mathbb{C}$,
\[
  \En_w(\omega, x) \;=\; \sum_{u \in V}\sum_{v \in V} w_{uv}\,
  \bigl\| x_v - \omega\,x_u \bigr\|^2 .
\]
\end{definition}

This is the Hermitian form $x^*(D - A_\omega)x$ of the rotated Laplacian; for
$\omega = 1$ it is the Dirichlet energy and for $\omega = -1$ the signless
energy.

\begin{definition}[Degree, volume, Rayleigh quotient]
The \emph{total degree} of $v$ is $d_v = \sum_u (w_{vu} + w_{uv})$, the sum of
out- and in-weights. The \emph{volume} of $x$ is
$\vol_w(x) = \sum_v d_v\|x_v\|^2$, and the \emph{rotated Rayleigh quotient} is
$\Ray_w(\omega,x) = \En_w(\omega,x)/\vol_w(x)$.
\end{definition}

\begin{definition}[Phase vector]
Fix $\omega$ with $|\omega| = 1$. A vector $x : V \to \mathbb{C}$ is a
\emph{phase vector} if for each $v$ either $x_v = 0$ or $x_v = \omega^k$ for
some $k \in \mathbb{N}$; it is \emph{unimodular} if in addition $\|x_v\| = 1$
for all $v$.
\end{definition}

For $\omega = -1$ the phase vectors are exactly the $\{-1,0,1\}$-vectors,
recovering Trevisan's test class.

\begin{definition}[Periodicity ratio]
Set $\PR_w(\omega) = \{\Ray_w(\omega,x) : x \ne 0 \text{ a phase vector}\}$ and
$\beta_w(\omega) = \inf \PR_w(\omega)$. We write $\beta_p = \beta_w(\omega_p)$
where $\omega_p = \exp(2\pi i/p)$.
\end{definition}

\begin{definition}[Walks and period]
Write $u \reach{n} v$ if there are $u = z_0,\dots,z_n = v$ with
$w_{z_i z_{i+1}} \ne 0$ for all $i$; $u \reach{0} u$ always. The digraph is
\emph{strongly connected} if for all $u,v$ there is $n$ with $u \reach{n} v$.
Its \emph{period} is $\gcd\{n \ge 1 : \exists v,\ v \reach{n} v\}$.
\end{definition}

\begin{definition}[Reversal]
The \emph{reversal} of $w$ is $w^\op_{uv} = w_{vu}$.
\end{definition}

\begin{definition}[Root gap]\label{def:gap}
For $p \ge 2$,
\[
  g_p \;=\; \min_{1 \le j \le p-1}\bigl\|\omega_p^{\,j} - 1\bigr\|^2
  \;=\; 4\sin^2(\pi/p),
\]
and $g_p = 0$ for $p < 2$. Thus $g_2 = 4$, $g_3 = 3$, $g_4 = 2$, $g_6 = 1$, and
$g_p \sim 4\pi^2/p^2$.
\end{definition}

We freely use that $\omega_p$ is a primitive $p$-th root of unity for
$p \ne 0$, that $\|\omega_p\| = 1$, and that $\omega_p^n = 1$ iff $p \mid n$.

\section{Basic properties}\label{sec:basic}

\begin{proposition}[Nonnegativity]
If $w \ge 0$ then $\En_w(\omega,x) \ge 0$ for all $\omega, x$.
\end{proposition}
\begin{proof}
Each summand is a product of nonnegative reals.
\end{proof}

\begin{lemma}[Sufficiency of the arc condition]\label{lem:suff}
If $x_v = \omega x_u$ whenever $w_{uv} \ne 0$, then $\En_w(\omega,x) = 0$. No
sign condition on $w$ is needed.
\end{lemma}
\begin{proof}
Every summand vanishes: either $w_{uv} = 0$, or $x_v - \omega x_u = 0$.
\end{proof}

\begin{theorem}[Zero energy is arc-local]\label{thm:zeroiff}
Assume $w \ge 0$. Then $\En_w(\omega,x) = 0$ if and only if $x_v = \omega x_u$
for every pair $(u,v)$ with $w_{uv} \ne 0$.
\end{theorem}
\begin{proof}
($\Leftarrow$) is Lemma~\ref{lem:suff}. For ($\Rightarrow$), a finite sum of
nonnegative terms vanishes only if every term does; applying this to the outer
and then the inner sum gives $w_{uv}\|x_v - \omega x_u\|^2 = 0$ for all $u,v$,
and $w_{uv} \ne 0$ then forces $x_v = \omega x_u$.
\end{proof}

Theorem~\ref{thm:zeroiff} is the pivot of the development: it converts the
analytic statement ``the Rayleigh quotient vanishes'' into the combinatorial
statement ``the phase advances by exactly one tick along every arc''.

\begin{theorem}[Universal upper bound]\label{thm:two}
Assume $w \ge 0$ and $|\omega| = 1$. Then $\En_w(\omega,x) \le 2\vol_w(x)$ for
every $x$; hence $\Ray_w(\omega,x) \le 2$ whenever $\vol_w(x) > 0$, and
$\beta_w(\omega) \le 2$.
\end{theorem}
\begin{proof}
Termwise, $\|x_v - \omega x_u\| \le \|x_v\| + \|x_u\|$ by the triangle
inequality and $|\omega| = 1$, and $(a+b)^2 \le 2a^2 + 2b^2$ gives
\[
  w_{uv}\|x_v - \omega x_u\|^2 \le w_{uv}\bigl(2\|x_v\|^2 + 2\|x_u\|^2\bigr).
\]
Summing over all pairs, the first group contributes
$2\sum_v(\sum_u w_{uv})\|x_v\|^2$ (in-degree part) and the second
$2\sum_u(\sum_v w_{uv})\|x_u\|^2$ (out-degree part); their sum is exactly
$2\sum_v d_v\|x_v\|^2 = 2\vol_w(x)$.
\end{proof}

\begin{lemma}\label{lem:revvol}
$d_v(w^\op) = d_v(w)$ for all $v$, and $\vol_{w^\op}(\bar x) = \vol_w(x)$.
\end{lemma}
\begin{proof}
$d_v$ is symmetric in in- and out-weights, and $\|\bar z\| = \|z\|$.
\end{proof}

\begin{lemma}[Conjugates are powers]\label{lem:conj}
If $\omega^N = 1$ with $N \ge 1$, then $\bar\omega = \omega^{N-1}$; hence the
conjugate of a phase vector is a phase vector.
\end{lemma}
\begin{proof}
$\omega^N = 1$ forces $|\omega| = 1$, so $\bar\omega\,\omega = 1$; also
$\omega\cdot\omega^{N-1} = 1$. Multiplying $\bar\omega$ by
$1 = \omega\,\omega^{N-1}$ and cancelling yields $\bar\omega = \omega^{N-1}$,
and $\overline{\omega^k} = \omega^{(N-1)k}$.
\end{proof}

\begin{theorem}[Reversal invariance]\label{thm:rev}
Let $|\omega| = 1$. Then $\En_{w^\op}(\omega,\bar x) = \En_w(\omega,x)$ for all
$w,x$. If moreover $\omega^N = 1$ for some $N \ge 1$, then
$\PR_{w^\op}(\omega) = \PR_w(\omega)$ and therefore
$\beta_{w^\op}(\omega) = \beta_w(\omega)$.
\end{theorem}
\begin{proof}
Swap the order of summation and compute the generic term. Using
$\bar\omega\,\omega = 1$,
\[
  \bar x_u - \omega\bar x_v = \overline{\,x_u - \bar\omega x_v\,}
  = \overline{\,-\bar\omega\,(x_v - \omega x_u)\,},
\]
so taking norms gives $\|\bar x_u - \omega\bar x_v\| = \|x_v - \omega x_u\|$.
The weight $w^\op$ attaches to the pair $(v,u)$ is $w_{uv}$, so after the swap
the two double sums agree termwise. Conjugation is an involution taking nonzero
phase vectors to nonzero phase vectors (Lemma~\ref{lem:conj}) preserving
numerator and denominator (Lemma~\ref{lem:revvol}), so it induces an inclusion
$\PR_{w^\op}(\omega)\subseteq \PR_w(\omega)$; applying it to $w^\op$ gives the
reverse inclusion, and infima agree.
\end{proof}

\section{The zero set of the periodicity ratio}\label{sec:zeroset}

\begin{lemma}[Phase transport]\label{lem:transport}
Suppose $x_v = \omega x_u$ for every arc $u\to v$ of nonzero weight. If
$u \reach{n} v$ then $x_v = \omega^n x_u$.
\end{lemma}
\begin{proof}
Induction on $n$: a walk of length $n+1$ is a walk of length $n$ to some $z$
followed by an arc $z \to v$, giving $x_v = \omega x_z = \omega^{n+1}x_u$.
\end{proof}

\begin{corollary}
Under the hypotheses of Lemma~\ref{lem:transport} with $\omega \ne 0$: if
$x_u \ne 0$ and $u \reach{n} v$ then $x_v \ne 0$. In a strongly connected
digraph a nonzero zero-energy vector vanishes nowhere.
\end{corollary}

\begin{theorem}[Zero energy forces divisibility]\label{thm:nec}
Let $w \ge 0$, $p \ge 1$, and suppose $\En_w(\omega_p,x) = 0$ with $x_v \ne 0$
for some vertex $v$. Then every closed walk based at $v$ has length divisible
by $p$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:zeroiff}, $x$ advances by $\omega_p$ along each arc. If
$v \reach{n} v$ then Lemma~\ref{lem:transport} gives
$(\omega_p^{\,n} - 1)x_v = 0$; as $x_v \ne 0$ we get $\omega_p^{\,n} = 1$, and
primitivity gives $p \mid n$.
\end{proof}

\begin{theorem}[Divisibility yields a certificate]\label{thm:suff}
Let $V \ne \emptyset$, $p \ge 1$, and let $w$ be strongly connected. If every
closed walk has length divisible by $p$, then there is a unimodular $p$-phase
vector $x$ with $\En_w(\omega_p,x) = 0$.
\end{theorem}
\begin{proof}
Fix a root $r$. For each $v$ choose a walk $r \reach{N(v)} v$ and set
$x_v = \omega_p^{\,N(v)}$; each $\|x_v\| = 1$. Let $w_{uv} \ne 0$ and choose a
walk $v \reach{k} r$. Concatenation yields two closed walks at $r$, of lengths
$N(v) + k$ and $N(u) + 1 + k$. By hypothesis $p$ divides both, so
$\omega_p^{N(v)+k} = 1 = \omega_p^{N(u)+1+k}$; cancelling the nonzero factor
$\omega_p^{\,k}$ gives $\omega_p^{N(v)} = \omega_p^{N(u)+1}$, i.e.
$x_v = \omega_p x_u$. Lemma~\ref{lem:suff} concludes.
\end{proof}

\begin{theorem}[Main characterization]\label{thm:main}
Let $V \ne \emptyset$, let $w \ge 0$ be strongly connected and let $p \ge 1$.
The following are equivalent:
\begin{enumerate}[label=(\arabic*)]
  \item there is a unimodular $p$-phase vector $x$ with $\En_w(\omega_p,x)=0$;
  \item $p$ divides the length of every closed walk of the digraph;
  \item $p$ divides the period of the digraph.
\end{enumerate}
Moreover (1) implies $\beta_p = 0$.
\end{theorem}
\begin{proof}
(1)$\Rightarrow$(2) is Theorem~\ref{thm:nec} (unimodularity gives $x_v \ne 0$);
(2)$\Rightarrow$(1) is Theorem~\ref{thm:suff}; (2)$\Leftrightarrow$(3) is the
definition of the period.
\end{proof}

\begin{corollary}[Closure under divisors]
If $\beta_p$ vanishes in the sense of (1) and $q \mid p$ with $q \ge 1$, then
$\beta_q$ vanishes.
\end{corollary}

\begin{corollary}[Closure under least common multiples]
If $\beta_p$ and $\beta_q$ vanish, so does $\beta_{\operatorname{lcm}(p,q)}$.
\end{corollary}

\begin{corollary}[Divisor-lattice structure]\label{cor:lattice}
For a strongly connected digraph of period $P$,
$\{p \ge 1 : \beta_p = 0 \text{ via a unimodular certificate}\}
 = \{p : p \mid P\}$.
\end{corollary}
\begin{proof}
The set contains $1$, is closed under divisors and lcm's, and has maximum $P$;
such a subset of $\mathbb{N}_{\ge 1}$ is exactly the divisor set of $P$.
\end{proof}

\begin{theorem}[The bold converse fails]\label{thm:counter}
There is a strongly connected nonnegatively weighted digraph on four vertices
admitting a unimodular phase vector of zero $2$-rotated energy in which no
closed walk has length $2$.
\end{theorem}
\begin{proof}
Let $V = \mathbb{Z}/4$ and let $C_4$ have $w_{u,u+1} = 1$ and all other weights
$0$; it is strongly connected since $u \reach{k} u+k$ for all $k$. An induction
shows $u \reach{n} v$ implies $v = u+n$ in $\mathbb{Z}/4$; taking $v = u$ gives
$4 \mid n$, so every closed walk has length divisible by $4$. Here
$\omega_2 = e^{\pi i} = -1$; put $x_v = (-1)^v$ using the representative
$v \in \{0,1,2,3\}$. Each $x_v$ is a unimodular power of $-1$, and every arc has
the form $u \to u+1$ with $(-1)^{u+1} = -(-1)^u = \omega_2 x_u$ (the wraparound
arc $3 \to 0$ satisfies $(-1)^0 = 1 = -(-1)^3$). By Lemma~\ref{lem:suff} the
energy is $0$. A closed walk of length $2$ would require $4 \mid 2$.
\end{proof}

Thus $\beta_p = 0$ certifies exactly $p \mid P$ and nothing more, consistent
with Corollary~\ref{cor:lattice}.

\section{Markov chains and unimodular eigenvalues}\label{sec:markov}

Let $P$ be stochastic ($P_{uv}\ge 0$, $\sum_v P_{uv} = 1$) with stationary
distribution $\pi$ ($\sum_u \pi_u P_{uv} = \pi_v$). Weight the digraph by the
stationary flow $w_{uv} = \pi_u P_{uv}$.

\begin{lemma}[Row variance identity]\label{lem:var}
Fix $u$, let $x : V \to \mathbb{C}$ and $c = \sum_v P_{uv}x_v$. Then
\[
  \sum_v P_{uv}\|x_v - c\|^2 = \Bigl(\sum_v P_{uv}\|x_v\|^2\Bigr) - \|c\|^2 .
\]
\end{lemma}
\begin{proof}
Expand $\|x_v - c\|^2 = \|x_v\|^2 + \|c\|^2 - 2\Real(x_v\bar c)$ and sum
against $P_{uv}$. Since the row sums to $1$, the middle term contributes
$\|c\|^2$ and the cross term $2\Real(c\bar c) = 2\|c\|^2$.
\end{proof}

This is $\mathbb{E}\|Z-\mathbb{E}Z\|^2 = \mathbb{E}\|Z\|^2 - \|\mathbb{E}Z\|^2$
for $Z = x_{V_1}$ under one step from $u$.

\begin{theorem}[Unimodular eigenvectors have zero energy]\label{thm:eig}
Let $\|\omega\| = 1$ and suppose $\sum_v P_{uv}x_v = \omega x_u$ for all $u$.
Then $\En_w(\omega,x) = 0$ for $w_{uv} = \pi_u P_{uv}$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:var} with $c = \omega x_u$; since $\|\omega\| = 1$,
$\|c\|^2 = \|x_u\|^2$, so
$\sum_v \pi_u P_{uv}\|x_v - \omega x_u\|^2
 = \pi_u\sum_v P_{uv}\|x_v\|^2 - \pi_u\|x_u\|^2$.
Summing over $u$, stationarity gives
$\sum_u\sum_v(\pi_uP_{uv})\|x_v\|^2 = \sum_v \pi_v\|x_v\|^2$, cancelling the
second part exactly.
\end{proof}

The mechanism: the eigenvector equation says the next phase is correct in
expectation; stationarity says the aggregate variance is zero; zero variance of
a nonnegative quantity forces pointwise correctness on every arc of positive
probability.

\begin{theorem}[Converse]\label{thm:eigconv}
Let $P \ge 0$ be stochastic and $\pi_v > 0$ for all $v$. If
$\En_w(\omega,x) = 0$ for $w_{uv} = \pi_uP_{uv}$, then
$\sum_v P_{uv}x_v = \omega x_u$ for all $u$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:zeroiff}, $\pi_uP_{uv} \ne 0$ implies
$x_v = \omega x_u$; as $\pi_u > 0$ this reads $P_{uv}\ne 0 \Rightarrow
x_v = \omega x_u$. Hence $P_{uv}x_v = P_{uv}(\omega x_u)$ for every $v$
(trivially when $P_{uv} = 0$); summing and using $\sum_v P_{uv} = 1$ concludes.
\end{proof}

\begin{corollary}[Peripheral spectrum forces divisibility]
If $x \ne 0$ is a right eigenvector of $P$ with eigenvalue $\omega_p$ and
$\pi \ge 0$ is stationary, then every closed walk of the flow-weighted digraph
based at a vertex where $x$ is nonzero has length divisible by $p$.
\end{corollary}
\begin{proof}
Combine Theorems~\ref{thm:eig} and~\ref{thm:nec}.
\end{proof}

Together, Theorems~\ref{thm:eig} and~\ref{thm:eigconv} say that for a chain
with everywhere-positive stationary distribution, unimodular eigenvalues and
zero rotated energy are the same phenomenon; this recovers, from the energy
viewpoint, the Perron--Frobenius description of the peripheral spectrum of an
irreducible stochastic matrix.

\section{Quantization of the periodicity energy}\label{sec:quant}

\begin{lemma}\label{lem:modp}
For $p \ge 1$, $\omega_p^m = \omega_p^n$ if and only if $m \equiv n \pmod p$.
\end{lemma}
\begin{proof}
With $n \le m$, $\omega_p^m = \omega_p^n$ iff $\omega_p^{m-n} = 1$ iff
$p \mid m-n$.
\end{proof}

\begin{lemma}[Uniform separation]\label{lem:sep}
For $p \ge 2$ we have $g_p > 0$, and $\|\omega_p^a - \omega_p^b\|^2 \ge g_p$
whenever $\omega_p^a \ne \omega_p^b$.
\end{lemma}
\begin{proof}
$g_p$ is a minimum over the finite nonempty set $\{1,\dots,p-1\}$ of the
quantities $\|\omega_p^{\,j}-1\|^2$, each strictly positive since
$\omega_p^{\,j} = 1$ would force $p \mid j$. For the separation, let
$j \in \{0,\dots,p-1\}$ be the residue of $a-b$ modulo $p$; $j = 0$ is excluded
by Lemma~\ref{lem:modp}, so $1 \le j \le p-1$, and
$\omega_p^a - \omega_p^b = \omega_p^b(\omega_p^{\,j}-1)$ with
$\|\omega_p^b\| = 1$, whence
$\|\omega_p^a - \omega_p^b\| = \|\omega_p^{\,j}-1\| \ge \sqrt{g_p}$.
\end{proof}

The closed form $g_p = 4\sin^2(\pi/p)$ follows from
$\|\omega_p^{\,j}-1\|^2 = 2-2\cos(2\pi j/p) = 4\sin^2(\pi j/p)$, minimized at
$j = 1$.

\begin{theorem}[Quantization]\label{thm:quant}
Let $w$ satisfy the \emph{unit-scale condition}: for all $u,v$, either
$w_{uv} = 0$ or $w_{uv} \ge 1$. Let $p \ge 2$ and let $x$ be a unimodular
$p$-phase vector, $x_v = \omega_p^{k_v}$. Then
\[
  \En_w(\omega_p,x) = 0 \qquad\text{or}\qquad
  \En_w(\omega_p,x) \ \ge\ g_p = 4\sin^2(\pi/p).
\]
\end{theorem}
\begin{proof}
The unit-scale condition implies $w \ge 0$. If $x_v = \omega_p x_u$ on every
arc of nonzero weight, the energy is $0$ by Lemma~\ref{lem:suff}. Otherwise
there are $u,v$ with $w_{uv} \ne 0$ and $x_v \ne \omega_p x_u$; then
$\omega_p^{k_v} \ne \omega_p^{k_u+1}$, so Lemma~\ref{lem:sep} gives
$\|x_v - \omega_p x_u\|^2 \ge g_p$. Since $w_{uv} \ne 0$ we have
$w_{uv} \ge 1$, so this single summand is at least $g_p$; all other summands
are nonnegative, so
\[
  \En_w(\omega_p,x) \ \ge\ \sum_z w_{uz}\|x_z - \omega_p x_u\|^2
  \ \ge\ w_{uv}\|x_v-\omega_px_u\|^2 \ \ge\ g_p. \qedhere
\]
\end{proof}

\begin{corollary}[Rigidity below the threshold]\label{cor:rigid}
Let $w$ satisfy the unit-scale condition, let $p \ge 2$, and let $x$ be a
unimodular $p$-phase vector with $\En_w(\omega_p,x) < g_p$. Then
$\En_w(\omega_p,x) = 0$ and every closed walk of the digraph has length
divisible by $p$.
\end{corollary}
\begin{proof}
Theorem~\ref{thm:quant} forces the energy to be $0$; each $x_v$ is a power of
$\omega_p$, hence nonzero, so Theorem~\ref{thm:nec} applies at every vertex.
\end{proof}

In words: on a unit-scale digraph, observing any phase assignment with energy
below $4\sin^2(\pi/p)$ is a proof of exact $p$-periodicity. There is no such
thing as being strictly, slightly, nearly $p$-periodic.

\begin{theorem}[Sharpness of the unit-scale hypothesis]\label{thm:sharp}
For every $\varepsilon > 0$ there is a strongly connected nonnegatively
weighted digraph on four vertices and a unimodular $3$-phase vector $x$ with
$0 < \En(\omega_3,x) < \varepsilon$.
\end{theorem}
\begin{proof}
Let $C_4(t)$ be the directed $4$-cycle of Theorem~\ref{thm:counter} with all
weights scaled by $t > 0$; scaling is linear in the energy,
$\En_{C_4(t)}(\omega,x) = t\,\En_{C_4}(\omega,x)$. Take $x \equiv 1$, a
unimodular $3$-phase vector. Each of the four arcs contributes
$\|1-\omega_3\|^2 = 2-2\cos(2\pi/3) = 3$, so
$E := \En_{C_4}(\omega_3,x) = 12 > 0$. Choosing
$t = \min\{1, \varepsilon/(2E)\} > 0$ preserves nonnegativity and the nonzero
pattern, hence strong connectivity, and gives $\En_{C_4(t)}(\omega_3,x) = tE$
with $0 < tE \le \varepsilon/2 < \varepsilon$.
\end{proof}

Since the failure is caused by global rescaling, which also rescales $\vol_w$,
the natural repair is to work with the scale-invariant ratio
$\En/\vol$ rather than the raw energy.

\section{Algorithms}\label{sec:algo}

\subsection{Exact period by phase propagation}
Theorem~\ref{thm:main} turns period computation into breadth-first search: fix
a root $r$, assign $N(v)$ the BFS depth, and for every arc $u \to v$ record the
discrepancy $\delta = N(u)+1-N(v)$. The period is the gcd of all discrepancies.
Correctness is exactly the statement that the certificate
$x_v = \omega_p^{N(v)}$ of Theorem~\ref{thm:suff} exists iff $p$ divides every
discrepancy. Cost: $O(|V| + |E|)$ operations plus $O(|E|)$ gcd's.

\subsection{Rotated spectrum and rounding}
For a candidate $p$, form $L_{\omega_p} = D - A_{\omega_p}$; its smallest
eigenvalue satisfies $\lambda_{\min}(p) \le \beta_p \le 2$, since phase vectors
are a subset of all vectors. Hence $\lambda_{\min}(p) > 0$ certifies
$\beta_p > 0$ and so, by Theorem~\ref{thm:main}, that $p$ does not divide the
period. Round the minimizing eigenvector $y$ to a phase vector by
\[
  x_v = \begin{cases}
    0, & \|y_v\| < \tau,\\[2pt]
    \omega_p^{\,k},\quad k = \bigl[\,p\arg(y_v)/2\pi\,\bigr] \bmod p,
      & \|y_v\| \ge \tau,
  \end{cases}
\]
and sweep $\tau$ over the sorted magnitudes, returning the best ratio. Each
rounded vector is an upper-bound certificate $\beta_p \le \Ray_w(\omega_p,x)$.

\subsection{Many nearly-periodic components}
Iterate: compute the best sweep set, record it as a component with its ratio,
remove or down-weight it, and repeat on the residual digraph until the
achievable ratio exceeds a target. Randomizing the starting eigenvector and the
sweep threshold yields a randomized polynomial-time procedure producing many
components of small periodicity ratio.

\subsection{Certification by rigidity}
On a unit-scale digraph, Corollary~\ref{cor:rigid} supplies a decisive test: a
rounded phase vector with energy below $4\sin^2(\pi/p)$ proves exact
$p$-periodicity. Since the energy of a phase vector is computable exactly in
$O(|E|)$ time, an approximate spectral computation is thereby converted into an
exact combinatorial certificate.

\section{Discussion}\label{sec:disc}

\subsection{Scope}
The zero set of $p \mapsto \beta_p$ is exactly the divisor lattice of the
period (Corollary~\ref{cor:lattice}); it does not see the period as an
\emph{attained} cycle length (Theorem~\ref{thm:counter}). The ratio is
normalized (Theorem~\ref{thm:two}) and reversal-symmetric
(Theorem~\ref{thm:rev}), so it is a genuine invariant of the weighted arc
structure. For Markov chains it is the peripheral spectrum in disguise.

\subsection{Where the gap comes from}
Two ingredients drive the quantization gap: the finiteness and uniform
separation of $\mu_p$, and a lower bound on nonzero weights. Removing the
latter destroys the conclusion (Theorem~\ref{thm:sharp}); allowing arbitrary
unimodular coordinates instead of roots of unity destroys it too, since a
continuously varying phase produces continuously varying energy. The gap is
exactly the interaction of a discrete alphabet with a fixed scale.

\subsection{The bipartite case}
At $p = 2$: $\omega_2 = -1$, phase vectors are $\{-1,0,1\}$-vectors, $\beta_2$
is the bipartiteness ratio and $g_2 = 4$. Rigidity reads: on a graph with all
nonzero weights at least $1$, a $\{-1,+1\}$ labelling with signless energy
below $4$ has energy $0$ and the graph is bipartite --- transparent, since a
single monochromatic edge costs $|1-(-1)|^2 = 4$.

\subsection{Limitations}
The threshold $g_p \approx 4\pi^2/p^2$ decays quadratically, so certifying
large periods needs proportionally precise energy computations. The
quantization theorem constrains phase vectors only; a general low-energy
eigenvector need not be quantized, so a lossy rounding step remains necessary.
Finally, the results here are structural; a two-sided Cheeger-type inequality
relating $\beta_p$ to $\lambda_{\min}(p)$ with explicit constants is a separate
matter.

\section{Future directions}

\begin{itemize}
  \item \textbf{A Cheeger inequality for the periodicity ratio.} Prove
  $\lambda_{\min}(p) \le \beta_p \le C(p)\sqrt{\lambda_{\min}(p)}$, the easy
  direction being immediate and the hard direction following a sweep-cut
  analysis over phase-rounded eigenvectors.
  \item \textbf{Higher-order versions.} Analyse the periodicity-ratio variant
  of higher-order spectral algorithms extracting $k$ nearly-periodic components
  simultaneously, with guarantees in terms of the $k$-th rotated eigenvalue.
  \item \textbf{Sharp scale-free quantization.} Determine the exact function
  $F(p,\Delta)$ such that on digraphs of maximum degree $\Delta$ the ratio of a
  phase vector is either $0$ or at least $F(p,\Delta)$.
  \item \textbf{Robustness of rigidity.} Quantify the dichotomy when the weight
  lower bound is $w_{\min} > 0$ (the threshold becomes $w_{\min}g_p$) and
  characterize the extremal digraphs.
  \item \textbf{Spectral gaps and mixing.} Relate $\beta_p$ for small $p$ to
  quantitative slow-mixing certificates for Markov chain Monte Carlo.
  \item \textbf{Beyond cyclic groups.} Replace $\mu_p$ by an arbitrary finite
  unitary group and ask which combinatorial invariants the resulting twisted
  Laplacians detect; the divisor-lattice theorem should become a statement
  about the holonomy image of the digraph.
\end{itemize}

